addLayer("sta", {
	name: t("Statistics", "统计"),
	symbol: "S",
	color: "#8a8a9a",
	resource: "Stats",
	row: "side",
	position: 1,
	startData() { return { unlocked: true, points: new Decimal(0) } },
	type: "none",
	tabFormat: [
		"main-display",
		["display-text", function() {
			var span = player.t.points.slog(10).sub(new Decimal("1e-64").slog(10));
			return "<table style='margin-left:5%'>";
				+ statRow(t("Truth now", "当前真值"), format(player.t.points))
				+ statRow(t("Truth best", "真值最高"), format(player.t.best))
				+ statRow(t("Truth total", "真值累计"), format(player.t.total))
				+ statRow(t("slog span", "slog 跨度"), format(span) + " / 8.02");
				+ statRow(t("F11", "F11"), format(TRUTH_F11));
				+ statRow(t("Era", "时代"), ["I Axioms", "II Proofs", "III Transcendence", "IV Infinity"][eraIndex()]);
				+ statRow(t("Ascensions", "飞升次数"), player.t.ascents);
				+ statRow("Proof Sparks " + t("(证明火花)", ""), format(player.t.sparks));
				+ statRow("Transcendence Charge " + t("(超越电荷)", ""), format(player.t.charge));
				+ statRow(t("Layer bonus", "层加成"), player.t.transcend.toString());
				+ statRow(t("Boards solved", "已解棋局"), player.t.boardsSolved);
				+ statRow(t("Upgrades owned", "已购升级"), player.t.upgrades.length + " / 300");
				+ statRow(t("Milestones", "里程碑"), player.t.milestones.length + " / 72");
				+ statRow(t("Achievements", "成就"), player.ach.achievements.length + " / 200");
				+ statRow(t("Trials cleared", "试炼通关"), trialCount() + " / 16");
				+ "</table>";
		}],
	],
})

function statRow(k, v) { return "<tr><td style='text-align:right;padding-right:12px'>" + k + "</td><td style='text-align:left'><b>" + v + "</b></td></tr>" }
function trialCount() {
	var ids = [11,12,13,14,21,22,23,24,31,32,33,34,41,42,43,44], c = 0;
	for (const id of ids) if (hasChallenge("t", id)) c++;
	return c;
}

addLayer("sto", {
	name: t("Deduction Log", "推理日志"),
	symbol: "D",
	color: "#d09ad0",
	resource: "Log",
	row: "side",
	position: 2,
	startData() { return { unlocked: true, points: new Decimal(0) } },
	type: "none",
	tabFormat: ["main-display", "storyLog"],
	microtabs: {
		storyLog: {
			Chapters: { unlocked() { return true }, content: STORY_TABS },
		},
	},
})

// Story lives in its own tab (handbook 10 §3-7), unlock-gated, never
// interleaved with buy buttons.
var STORY_TABS = [
	["display-text", function() {
		var out = "";
		for (var i = 0; i < STORY.length; i++) {
			if (eraIndex() + 1 >= STORY[i].era) {
				out += "<h3 style='color:" + STORY[i].color + "'>" + STORY[i].en + " / " + STORY[i].zh + "</h3>";
				out += "<div style='margin-bottom:14px; line-height:1.65'>" + STORY[i].body + "</div>";
			}
		}
		return out || t("<i>The log is empty. Prove something.</i>", "<i>日志尚空。去证明点什么。</i>");
	}],
];

var STORY = [
	{ era: 0, color: "#3b6ea5", en: t("The Tenth Place", "第十位"), zh: "第十位",
	  body: t("A number so small it is almost not there: 10^-64. Every mathematician starts here, at the edge of what can be written.", "第十位：A number so……") },
	{ era: 1, color: "#4f9d69", en: t("Axioms", "公理"), zh: "公理",
	  body: t("You accept things without proving them, so that you may prove everything else. The bars fill; sparks fall.", "公理：You accept things……") },
	{ era: 2, color: "#4f9d69", en: t("Proofs", "证明"), zh: "证明",
	  body: t("A proof is a chain with no broken link. You click, you bank, and the chain is walked whether or not you watch.", "证明：A proof is……") },
	{ era: 3, color: "#8a5fbf", en: t("Transcendence", "超越"), zh: "超越",
	  body: t("Some truths cannot be reached from below. They must be assembled, symbol by symbol, on a board that only opens once.", "超越：Some truths cannot……") },
	{ era: 4, color: "#c9a227", en: t("The Ascent", "飞升"), zh: "飞升",
	  body: t("Each rung of the ascent adds a whole layer to your number. You are not multiplying. You are changing what multiplication means.", "飞升：Each rung of……") },
	{ era: 5, color: "#c9a227", en: t("F₁₁", "F₁₁"), zh: "F₁₁",
	  body: t("Six tens, topped with eleven. F = 10^10^10^10^10^10 sits just below you; F₁₁ sits just above. You have passed both.", "F₁₁：Six tens, topped……") },
];

function clickTotal(layer) {
	var c = 0;
	for (var i = 11; i <= 20; i++) c += getClickableState(layer, i) || 0;
	return c;
}
function ladderTotal(layer) {
	return getBuyableAmount(layer, 11).toNumber() + getBuyableAmount(layer, 12).toNumber()
	     + getBuyableAmount(layer, 13).toNumber() + getBuyableAmount(layer, 14).toNumber()
	     + player[layer].ascents;
}
